using System;
using System.Collections.Generic;
using System.IO;
using System.Security.Cryptography;
using HeroCat.Runtime.Save;
using HeroCat.Sim.Replay;
using Newtonsoft.Json.Linq;
using NUnit.Framework;

namespace HeroCat.Runtime.Tests
{
    /// <summary>
    /// 02 section 7.3 M1-M7 (issue #76). The chain starts at the new v1: the old prototype's saves are not migrated
    /// (00 decision 33). Fixtures/Saves/v1.json is generated by the bot CLI (`save-fixture --update`), never by hand;
    /// check.sh drift-checks it until SaveSchema.V1Frozen.
    /// </summary>
    public class MigrationTests : TempDirTest
    {
        static string FixtureDir => Path.Combine(TestContent.RepoRoot, "src", "HeroCat.Runtime.Tests", "Fixtures", "Saves");

        static JObject Fixture(int v) => SaveSerializer.ParseBody(File.ReadAllText(Path.Combine(FixtureDir, $"v{v}.json")));

        sealed class Recording : IMigrationLog
        {
            public readonly List<(int, int)> Steps = new List<(int, int)>();
            public void Applied(int from, int to) => Steps.Add((from, to));
        }

        [Test]
        public void M1_StepCount_IsCurrentMinusOne()
        {
            Assert.That(SaveSchema.Current, Is.EqualTo(1));
            Assert.That(SaveMigrations.Steps.Count, Is.EqualTo(SaveSchema.Current - 1));
        }

        // M2 (each step against v{n}.to.v{n+1}.expected.json) has no case until v2 exists.

        [Test]
        public void M3_EveryFixture_MigratesMaterializesAndValidates()
        {
            for (int v = 1; v <= SaveSchema.Current; v++)
            {
                var body = SaveMigrations.Migrate(v, Fixture(v));
                var state = SaveSerializer.Materialize(body);
                Assert.DoesNotThrow(() => SaveSystem.Validate(state, TestContent.Db), $"v{v}");
                // TODO(#75): and zero repairs once the repair rules exist.
            }
        }

        [Test]
        public void M4_StepsArePure_TheDriverRunsWithoutContentOrClock()
        {
            // The step signature JObject -> JObject has no ContentDb or IClock to reach; this pins the driver on a synthetic
            // chain so a future step cannot sneak a dependency in through the driver.
            var log = new Recording();
            var chain = new Func<JObject, JObject>[] { j => { j["Added"] = 1; return j; }, j => { j["Added"] = (int)j["Added"] + 1; return j; } };
            var outBody = SaveMigrations.Migrate(1, new JObject { ["SchemaVersion"] = 1 }, chain, 3, log);
            Assert.That((int)outBody["SchemaVersion"], Is.EqualTo(3));
            Assert.That((int)outBody["Added"], Is.EqualTo(2));
            Assert.That(log.Steps, Is.EqualTo(new[] { (1, 2), (2, 3) }));
        }

        [Test]
        public void M5_FrozenV1_HashMatches()
        {
            if (!SaveSchema.V1Frozen) Assert.Ignore("v1 is not frozen yet (02 section 7.4); check.sh drift-checks v1.json instead");
            string expected = File.ReadAllText(Path.Combine(FixtureDir, "v1.sha256")).Trim();
            using var sha = SHA256.Create();
            string actual = BitConverter.ToString(sha.ComputeHash(File.ReadAllBytes(Path.Combine(FixtureDir, "v1.json")))).Replace("-", "").ToLowerInvariant();
            Assert.That(actual, Is.EqualTo(expected));
        }

        [Test]
        public void M6_MigrateMaterializeEncodeDecode_IsIdempotent()
        {
            var a = SaveSerializer.Materialize(SaveMigrations.Migrate(1, Fixture(1)));
            var (b, _, _) = SaveSystem.DecodeFull(SaveSerializer.Encode(a), TestContent.Db);
            Assert.That(StateEquality.Equal(a, b), Is.True);
        }

        [Test]
        public void M7_TooNew_Throws_AndTheStoreDoesNotConsultPrev()   // acceptance 8
        {
            var body = SaveSerializer.ToJson(TestContent.NewState());
            body["SchemaVersion"] = SaveSchema.Current + 1;
            var store = new MemorySaveStore
            {
                Primary = SaveSerializer.EncodeBody(body.ToString()),
                Backup = SaveSerializer.Encode(TestContent.NewState()),
            };
            var e = Assert.Throws<SaveTooNewException>(() => SaveSystem.Load(store, TestContent.Db, TestContent.T0));
            Assert.That(e.Found, Is.EqualTo(SaveSchema.Current + 1));
            Assert.That(store.Quarantined, Is.Empty);
            Assert.That(store.Primary, Is.Not.Null, "nothing renamed");
        }

        [Test]
        public void OldDesignDevSave_IsQuarantined_AndTheSessionStartsANewProfile()
        {
            // Captured from the old prototype build before the M0 rewrite (header without v= / hmac=, Meta/State wrapper).
            var old = File.ReadAllBytes(Path.Combine(FixtureDir, "old-design-dev.sav"));
            var store = new FileSaveStore(Dir);
            File.WriteAllBytes(store.PrimaryPath, old);
            var analytics = new HeroCat.Runtime.Services.MemoryAnalytics();
            var session = HeroCat.Runtime.Session.GameSession.Open(TestContent.Db, new HeroCat.Runtime.Services.GameServices
            {
                Clock = new HeroCat.Runtime.Services.FakeClock(TestContent.T0 + 100), SaveStore = store, Analytics = analytics,
            });
            Assert.That(session.LoadResult.Status, Is.EqualTo(LoadStatus.Corrupt));
            Assert.That(session.IsNewProfile, Is.True);
            Assert.That(store.QuarantinedFiles(), Has.Length.EqualTo(1));
            Assert.That(SaveSystem.Load(store, TestContent.Db, TestContent.T0 + 100).Status, Is.EqualTo(LoadStatus.Loaded));
        }
    }
}
